--
-- MODE: ENFORCING
-- Database: read_order   Owner: migrator   Writer: projector_order
--
-- Database-level security for the #638 chunk-1 table set (PROP-20260818-010343).
-- Applied by crates/infrastructure/tests/rls_matrix.rs to throwaway databases, and by
-- NOTHING else: no file under migrations/ may carry ROW LEVEL SECURITY, CREATE POLICY or
-- CREATE ROLE (tools/codegen-rs/src/tests.rs, security_ddl_fence). db-migrate.yml runs
-- `sqlx migrate run` against the real DATABASE_URL on `workflow_run: [deploy] completed`,
-- and production is suspended by a DECISION, not by physics.
--
-- Two artifacts come off this one emitter: `security.generated.sql` (enforcing) and
-- `security.permissive.generated.sql`. The permissive one is what ships first and what the
-- tightening step reverts TO -- #637: a policy is subtractive on reads, so ADR-0043's
-- `redeploy the previous app` is a no-op against it, and the only rollback is a forward,
-- GENERATED migration that is the permissive emission of the same table.
--
-- Re-runnable: DO $$ guards on CREATE ROLE, DROP POLICY IF EXISTS before every CREATE
-- POLICY, no psql metacommand, valid as ONE multi-statement simple query.

-- ─── 1. ROLES ──────────────────────────────────────────────────────────────
-- NOLOGIN, exactly like migrations/20260808070000_claude_ro_select_only.sql: role LIFECYCLE
-- (login, password) belongs to the platform (CNPG `managed.roles`), and this repository is
-- public. NOBYPASSRLS on every one of them is the invariant gate G-6 asserts -- a role
-- attribute is not scoped to a table, so BYPASSRLS bypasses on tables it was never meant
-- to. NOINHERIT so a granted persona is reached only by an explicit SET ROLE.
-- Idempotent, and it degrades the way the house pattern degrades: a migration user without
-- CREATEROLE gets a NOTICE, not a failure.

DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['admin_role', 'customer_role', 'migrator', 'projector_order', 'restaurant_role', 'rider_role'] LOOP
    IF NOT EXISTS (SELECT FROM pg_catalog.pg_roles WHERE rolname = r) THEN
      BEGIN
        EXECUTE format('CREATE ROLE %I NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS NOINHERIT', r);
      EXCEPTION WHEN insufficient_privilege THEN
        RAISE NOTICE 'role % not created (this user lacks CREATEROLE) -- create it out of band and re-run', r;
      END;
    END IF;
  END LOOP;
END $$;

-- ─── 2. OWNERSHIP ──────────────────────────────────────────────────────────
-- The business schema is owned by the declared owner of its database
-- (databases.yaml#/<database>/owner), NOT by whichever superuser ran the chain.
-- This is not tidiness. `FORCE ROW LEVEL SECURITY` removes only the OWNER's exemption and
-- never the superuser bypass, so a superuser-owned table makes FORCE observationally inert
-- and a suite asserting it passes over a configuration that proves nothing.

ALTER TABLE orderconversation OWNER TO migrator;
ALTER TABLE scopemembership OWNER TO migrator;

-- ─── 3. GRANTS ─────────────────────────────────────────────────────────────
-- ENFORCING: per-column SELECT. Native column grants rather than per-role masking views
-- (PROP-20260818-010343 §11.4): same outcome, roughly half the surface, no
-- view-owner-versus-FORCE interaction, and visible in information_schema.column_privileges.

GRANT USAGE ON SCHEMA public TO admin_role, customer_role, migrator, projector_order, restaurant_role, rider_role;
GRANT SELECT (scope_type, scope_id, member_type, member_id) ON scopemembership TO customer_role;
GRANT SELECT (scope_type, scope_id, member_type, member_id) ON scopemembership TO restaurant_role;
GRANT SELECT (scope_type, scope_id, member_type, member_id) ON scopemembership TO rider_role;
GRANT SELECT (order_id, restaurant_id, customer_chat_enabled, status, messages, opened_at, admin_invited, escalation_reason, muted, claim_events, created_at, updated_at) ON orderconversation TO customer_role;
GRANT SELECT (order_id, restaurant_id, customer_chat_enabled, status, messages, internal_notes, opened_at, admin_invited, escalation_reason, muted, claim_events, created_at, updated_at) ON orderconversation TO restaurant_role;
GRANT SELECT (order_id, restaurant_id, customer_chat_enabled, status, messages, opened_at, admin_invited, escalation_reason, muted, claim_events, created_at, updated_at) ON orderconversation TO rider_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON orderconversation TO projector_order;
GRANT SELECT, INSERT, UPDATE, DELETE ON scopemembership TO projector_order;

-- ─── 4. WRITE POLICIES ─────────────────────────────────────────────────────
-- Under ENABLE + FORCE with only FOR SELECT policies, a writer's INSERT errors loudly while
-- its UPDATE and DELETE return 0 rows, COMMIT, and report success -- and a projector's fold
-- is mostly updates. It advances its checkpoint over a stream whose effects never land: the
-- dashboards stay green, checkpoint lag reads zero, and the read model is frozen. At Friday
-- peak that is order statuses that stop moving while everything reports healthy.
-- FOR ALL ... USING(true) WITH CHECK(true) rather than ALTER ROLE ... BYPASSRLS: visible in
-- pg_policies, therefore assertable, and it keeps the NOBYPASSRLS invariant whole.
-- WITH CHECK (true) deliberately, NOT the reader predicate: inheriting it would make a
-- rebuild depend on ScopeMembership already being caught up in the same database, and a read
-- model whose rebuild depends on another read model's checkpoint is no longer a disposable
-- projection.

DROP POLICY IF EXISTS orderconversation_write_projector_order ON orderconversation;
CREATE POLICY orderconversation_write_projector_order ON orderconversation
  FOR ALL TO projector_order
  USING (true)
  WITH CHECK (true);

DROP POLICY IF EXISTS scopemembership_write_projector_order ON scopemembership;
CREATE POLICY scopemembership_write_projector_order ON scopemembership
  FOR ALL TO projector_order
  USING (true)
  WITH CHECK (true);

-- NO owner policy in ENFORCING mode: `migrator` is subject to FORCE and holds no write
-- policy, so a backfill run as the owner returns `UPDATE 0` -- a correct refusal. A
-- migration that needs to write an RLS-bearing table must SET ROLE projector_order (G-6).

-- ─── 5. READ POLICIES ──────────────────────────────────────────────────────
-- ENFORCING: the member TYPE is a LITERAL bound to the database role -- one policy per
-- (table x role), never one policy naming four roles. The moment a policy has to work
-- out WHICH of its roles is calling, the member type comes back as caller-settable
-- data: on PG 16.13 a rider connection that ran `set_config('app.member_type',
-- 'CUSTOMER')` read two customer orders. Postgres gates SET ROLE; it does not gate a
-- set_config. That difference is the whole design.

DROP POLICY IF EXISTS scopemembership_read_customer_role ON scopemembership;
CREATE POLICY scopemembership_read_customer_role ON scopemembership
  FOR SELECT TO customer_role
  USING (member_type = 'CUSTOMER' AND member_id = nullif(current_setting('app.member_id', true), '')::uuid);

DROP POLICY IF EXISTS scopemembership_read_restaurant_role ON scopemembership;
CREATE POLICY scopemembership_read_restaurant_role ON scopemembership
  FOR SELECT TO restaurant_role
  USING (member_type = 'RESTAURANT' AND member_id = nullif(current_setting('app.member_id', true), '')::uuid);

DROP POLICY IF EXISTS scopemembership_read_rider_role ON scopemembership;
CREATE POLICY scopemembership_read_rider_role ON scopemembership
  FOR SELECT TO rider_role
  USING (member_type = 'RIDER' AND member_id = nullif(current_setting('app.member_id', true), '')::uuid);

DROP POLICY IF EXISTS orderconversation_read_customer_role ON orderconversation;
CREATE POLICY orderconversation_read_customer_role ON orderconversation
  FOR SELECT TO customer_role
  USING (EXISTS (SELECT 1 FROM scopemembership m
           WHERE m.scope_type  = 'ORDER'
             AND m.scope_id    = orderconversation.order_id
             AND m.member_type = 'CUSTOMER'
             AND m.member_id   = nullif(current_setting('app.member_id', true), '')::uuid));

DROP POLICY IF EXISTS orderconversation_read_restaurant_role ON orderconversation;
CREATE POLICY orderconversation_read_restaurant_role ON orderconversation
  FOR SELECT TO restaurant_role
  USING (EXISTS (SELECT 1 FROM scopemembership m
           WHERE m.scope_type  = 'ORDER'
             AND m.scope_id    = orderconversation.order_id
             AND m.member_type = 'RESTAURANT'
             AND m.member_id   = nullif(current_setting('app.member_id', true), '')::uuid));

-- ─── 6. ENABLE + FORCE ROW LEVEL SECURITY ──────────────────────────────────
-- LAST, so that at COMMIT no table is ever enabled without its policies.
-- FORCE is invisible in the table DDL -- an ALTER beside the CREATE, not inside it -- so a
-- newly generated projection table is born unFORCEd and wide open with nothing on the page
-- to notice. With NO FORCE the measured result was a full cross-order read through a view
-- whose text reads correctly. It is a generated invariant plus a CI assertion (G-3), never a
-- hand-written line: the assertion is behavioural (relrowsecurity AND relforcerowsecurity
-- over the derived table set), never by filename.

ALTER TABLE orderconversation ENABLE ROW LEVEL SECURITY;
ALTER TABLE orderconversation FORCE ROW LEVEL SECURITY;
ALTER TABLE scopemembership ENABLE ROW LEVEL SECURITY;
ALTER TABLE scopemembership FORCE ROW LEVEL SECURITY;
